INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (42, '<p>Write a function that takes an array and a number as an argument. if the number is greater than 0', 'p-write-a-function-that-takes-an-array-and-a-number-as-an-argument-if-the-number-is-greater-than-0', '<p>Write a function that takes an array and a number as an argument. if the number is greater than 0, you must pop the number of elements from the array. if the number is not provided then pop once.</p>', '29e42f35468376e69eb5a86e24e616ec20b20d803171324761f1891de283ebde', 0, 0, NULL, NULL);
