INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (74, '<p>Given a list of examples, which of them is an example of compile-time polymorphism?</p>', 'p-given-a-list-of-examples-which-of-them-is-an-example-of-compile-time-polymorphism-p', '<p>Given a list of examples, which of them is an example of compile-time polymorphism?</p>', 'd154c32965fe5f1655e9e33c2d557dc91ed9879b6e0fb32d33426754e193d2ac', 0, 0, NULL, NULL);
INSERT INTO companyquestions (id, company_id, question_id) VALUES (74, 4, 74);
INSERT INTO solutions (id, question_id, created_by, code, language, status, runtime, memory) VALUES (38, 74, NULL, '<p>Function overloading is an example of compile-time polymorphism. It allows multiple functions with the same name but different parameters to be defined in a class.</p>', 'C++', NULL, NULL, NULL);
INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (75, '<p>You are given a list of n unique room numbers belonging to guests at a hotel. These numbers are i', 'p-you-are-given-a-list-of-n-unique-room-numbers-belonging-to-guests-at-a-hotel-these-numbers-are-i', '<p>You are given a list of n unique room numbers belonging to guests at a hotel. These numbers are in the range <code>[0, n]</code>, but one guest''s room number is missing from the list. What is the best possible space complexity for solving this problem?</p>', 'f08be22793cbda3c5433862da27db5c113882fed954f3a4d767eb1468dcacbab', 0, 0, NULL, NULL);
INSERT INTO companyquestions (id, company_id, question_id) VALUES (75, 4, 75);
INSERT INTO solutions (id, question_id, created_by, code, language, status, runtime, memory) VALUES (39, 75, NULL, '<p>The best possible space complexity is <code>O(1)</code>. We can use the XOR operation to find the missing room number without using additional space. XOR all the room numbers in a variable <code>x</code>. Then XOR <code>x</code> with the range <code>[0, n]</code> and the missing room number will be the result.</p>', 'plaintext', NULL, NULL, NULL);
