INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (82, '<p>Given a number <code>n</code>, write a program to find if the number is an armstrong number or no', 'p-given-a-number-code-n-code-write-a-program-to-find-if-the-number-is-an-armstrong-number-or-no', '<p>Given a number <code>n</code>, write a program to find if the number is an armstrong number or not.</p><p>An Armstrong number is a number that is equal to the sum of its digits, each raised to the power of the number of digits in the number. For example, <code>153</code> is an Armstrong number because <code>1^3+5^3+3^3=153</code></p>', 'd1ca1586decfe0250666822714974fd23f93aa95a3ef986848ff8b0fa2d07f25', 0, 0, NULL, NULL);
