INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (87, '<p>Given an unsorted array of integers <code>nums</code>, return the length of the longest consecuti', 'p-given-an-unsorted-array-of-integers-code-nums-code-return-the-length-of-the-longest-consecuti', '<p>Given an unsorted array of integers <code>nums</code>, return the length of the longest consecutive elements sequence.:</p><p>Ex: Input: <code>5 3 2 1</code> After Sort: <code>1 2 3 5</code> Ans: <code>3</code><br> Bonus: Write an algorithm that runs in <code>O(n)</code> time.</p><p><strong>💻 Submit Code</strong></p>', 'd5eba0ea5e7f7016bd6f47e2f7d1c6c935c62c9d485b96df3b7895d0f7487f01', 0, 0, NULL, NULL);
