INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (88, '<p>Given two integers N (upto 18 digits) and M(≤100): Digits of the New Number:</p><ul><li>The new n', 'p-given-two-integers-n-upto-18-digits-and-m-100-digits-of-the-new-number-p-ul-li-the-new-n', '<p>Given two integers N (upto 18 digits) and M(≤100): Digits of the New Number:</p><ul><li>The new number should be formed by permuting the digits of N.</li><li>The new number must not have any leading zeros.</li><li>The new number must be divisible by M. find the num of numbers that match these conditions.</li></ul>
<pre><code>Input: 104 2
Output: 3
→104, 140, 410</code></pre>', 'd7b5d33a9d5a9b6fe996de1848be62e05f7254817efb4eec98bf693ac2085c11', 0, 0, NULL, NULL);
