INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (89, '<p>A customer reaches out with a complaint about a product they purchased. They are clearly frustrat', 'p-a-customer-reaches-out-with-a-complaint-about-a-product-they-purchased-they-are-clearly-frustrat', '<p>A customer reaches out with a complaint about a product they purchased. They are clearly frustrated, but the issue falls outside the company’s usual return policy.</p><p><strong>Options:</strong><br> A) Stick to company policy and explain why you can’t help them.<br> B) Make an exception to satisfy the customer.</p><p><strong>Scale:</strong><br> 1️⃣ Strongly Prefer A 2️⃣ Moderately Prefer A 3️⃣ Neutral 4️⃣ Moderately Prefer B 5️⃣ Strongly Prefer B</p>', 'f5a0360f352a556d01fc18d95528619f2fe8b0f8e7df619316f54235e08f8292', 0, 0, NULL, NULL);
