INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (91, '<p>You and a coworker are working on a project together. They propose an approach that you don’t ful', 'p-you-and-a-coworker-are-working-on-a-project-together-they-propose-an-approach-that-you-dont-ful', '<p>You and a coworker are working on a project together. They propose an approach that you don’t fully agree with, but they seem confident it will work.</p><p><strong>Options:</strong><br> A) Trust their judgment and follow their lead.<br> B) Insist on discussing the approach further before moving forward.</p><p><strong>Scale:</strong><br> 1️⃣ Strongly Prefer A 2️⃣ Moderately Prefer A 3️⃣ Neutral 4️⃣ Moderately Prefer B 5️⃣ Strongly Prefer B</p>', 'cb31b98fd8c8b2a1e5aeeadc8efd9bbe09148c7cb5511ac188673a41d1f1a9ef', 0, 0, NULL, NULL);
