INSERT INTO companyquestions (id, company_id, question_id) VALUES (103, 4, 103);
INSERT INTO solutions (id, question_id, created_by, code, language, status, runtime, memory) VALUES (50, 103, NULL, '<p><img alt="" src="https://d14qv6cm1t62pm.cloudfront.net/ccbp-website/Blogs/home/diamond-problem-in-java-explained-with-examples-and-solutions-image-1.png"/> Diamond Problem is a problem faced during Multiple Inheritance in Java. This problem occurs when a class inherits from two interfaces that both extend a common interface and define a method with the same name. The ambiguity arises because the class implementing these interfaces does not know which method to call when invoking the method by name.</p>', 'C++', NULL, NULL, NULL);
INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (104, '<p>Does Java support multiple inheritence?</p>', 'p-does-java-support-multiple-inheritence-p', '<p>Does Java support multiple inheritence?</p>', '602b9fff67c9421e27f0773ab7d8778319ec05c90e9fe8904d86e8c1de7c909b', 0, 0, NULL, NULL);
