INSERT INTO solutions (id, question_id, created_by, code, language, status, runtime, memory) VALUES (51, 104, NULL, '<p>Java doesn''t allow multiple inheritance to avoid the complexity and ambiguity associated with it, particularly the "diamond problem," where a class inherits from two classes that have a common ancestor, leading to conflicts in the inheritance of methods.</p><p>Read more from <a href="https://medium.com/@ByteCodeBlogger/diamonds-arent-a-developer-s-best-friend-tackling-the-diamond-problem-in-java-1bde9647f6e9" rel="noreferrer" target="_blank">Diamonds Aren’t a Developer’s Best Friend: Tackling the Diamond Problem in Java</a></p>', 'C++', NULL, NULL, NULL);
INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (105, '<p>How does Java tackle the multiple inheritence issue?</p>', 'p-how-does-java-tackle-the-multiple-inheritence-issue-p', '<p>How does Java tackle the multiple inheritence issue?</p>', 'f08b5fa48a9040716ce8430cd6c440f75a16d25e332a7c381b5b75b5cecd7333', 0, 0, NULL, NULL);
