INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (111, '<p>There is an array initially containing n numbers. then each of the numbers of the array is multip', 'p-there-is-an-array-initially-containing-n-numbers-then-each-of-the-numbers-of-the-array-is-multip', '<p>There is an array initially containing n numbers. then each of the numbers of the array is multiplied by 2. Now the array is 2 * n size and each element of the array gets shuffled. You are given the shuffled array of size 2 * n. You have to restore the original array.</p><p><strong>💻 Submit Code</strong></p>', '4f81577f83209f3fb544a6065191c0ccc0a59c5085c91a3983a61b9b51c8eadc', 0, 0, NULL, NULL);
