INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (122, '<p>Difference between Array and Linked List.</p>', 'p-difference-between-array-and-linked-list-p', '<p>Difference between Array and Linked List.</p>', '427280be25da10b77eceec1b25a805526417c4e8e68a6860c27cfd6337962d39', 0, 0, NULL, NULL);
