INSERT INTO solutions (id, question_id, created_by, code, language, status, runtime, memory) VALUES (57, 122, NULL, '<ul><li><strong>Array</strong>: An array is a collection of elements of the same data type stored in contiguous memory locations. It has a fixed size and allows random access to elements using an index.</li><li><strong>Linked List</strong>: A linked list is a data structure that consists of nodes where each node contains data and a reference (link) to the next node in the sequence. It does not require contiguous memory allocation and allows dynamic memory allocation.</li></ul><p>Read more from <a href="https://www.geeksforgeeks.org/array-vs-linked-list/" rel="noreferrer" target="_blank">Array vs Linked List | GeeksforGeeks</a></p>', 'plaintext', NULL, NULL, NULL);
INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (123, '<p>Which sorting algorithm works better in the average case?</p>', 'p-which-sorting-algorithm-works-better-in-the-average-case-p', '<p>Which sorting algorithm works better in the average case?</p>', 'dbc67d88ebe57305f72cb9070ac3bba0f0273fe0117551fa8fdf051c0ff91353', 0, 0, NULL, NULL);
INSERT INTO companyquestions (id, company_id, question_id) VALUES (123, 6, 123);
INSERT INTO solutions (id, question_id, created_by, code, language, status, runtime, memory) VALUES (58, 123, NULL, '<p>Merge sort and Quick sort work better in the average case. Merge sort has a time complexity of <code>O(nlogn)</code> in the worst case. Quick sort has a time complexity of <code>O(nlogn)</code> in the average case. Both are stable sorting algorithms and work well with large and medium datasets.</p>', 'plaintext', NULL, NULL, NULL);
INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (124, '<p>Suppose, you have to sort 1000 numbers, numbers can be positive and negative. Which algorithm wil', 'p-suppose-you-have-to-sort-1000-numbers-numbers-can-be-positive-and-negative-which-algorithm-wil', '<p>Suppose, you have to sort 1000 numbers, numbers can be positive and negative. Which algorithm will you use?</p>', 'db375075f661c861bebdf7b6588817eabb6d2961c05c62c3197f1fca790b0e27', 0, 0, NULL, NULL);
INSERT INTO companyquestions (id, company_id, question_id) VALUES (124, 6, 124);
INSERT INTO solutions (id, question_id, created_by, code, language, status, runtime, memory) VALUES (59, 124, NULL, '<p>We can use merge sort to sort the 1000 numbers. Merge sort has a time complexity of <code>O(nlogn)</code> in the worst case. It is a stable sorting algorithm and works well with large and medium datasets. Merge sort is a divide and conquer algorithm.</p>', 'plaintext', NULL, NULL, NULL);
INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (125, '<p>What is Stack, Queue and Priority Queue?</p>', 'p-what-is-stack-queue-and-priority-queue-p', '<p>What is Stack, Queue and Priority Queue?</p>', 'f468f9b3cb97fdc27bab4009c9e93e3443c320967dff28880d84f49062eec814', 0, 0, NULL, NULL);
INSERT INTO companyquestions (id, company_id, question_id) VALUES (125, 6, 125);
INSERT INTO solutions (id, question_id, created_by, code, language, status, runtime, memory) VALUES (60, 125, NULL, '<ul><li><strong>Stack</strong>: A stack is a linear data structure that follows the Last In First Out (LIFO) principle. It has two main operations: push (insert) and pop (remove).</li><li><strong>Queue</strong>: A queue is a linear data structure that follows the First In First Out (FIFO) principle. It has two main operations: enqueue (insert) and dequeue (remove).</li><li><strong>Priority Queue</strong>: A priority queue is a data structure that stores elements based on their priority. It allows elements with higher priority to be dequeued before elements with lower priority.</li></ul>', 'plaintext', NULL, NULL, NULL);
INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (126, '<p>Difference between Binary Tree and BST.</p>', 'p-difference-between-binary-tree-and-bst-p', '<p>Difference between Binary Tree and BST.</p>', 'aa00c1fc443e5e38c850228678d18d70b98e8563760cdd13fd0d693deb0183b5', 0, 0, 1, 21);
INSERT INTO companyquestions (id, company_id, question_id) VALUES (126, 6, 126);
INSERT INTO questiontopics (id, question_id, topic_id) VALUES (41, 126, 3);
INSERT INTO solutions (id, question_id, created_by, code, language, status, runtime, memory) VALUES (61, 126, NULL, '<ul><li><strong>Binary Tree</strong>:A binary tree is a tree data structure in which each node has at most two children, which are referred to as the left child and the right child.</li><li><strong>Binary Search Tree</strong>: A binary search tree is a binary tree in which the value of the left child is less than the parent node and the value of the right child is greater than the parent node.</li></ul><p>If the binary search tree is imbalanced, then we can make it balanced by using AVL tree or Red-Black tree. These trees are self-balancing binary search trees.</p>', 'plaintext', NULL, NULL, NULL);
INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (127, '<p>When we type a web address (www.google.com) in a web browser, what happens before we get the resp', 'p-when-we-type-a-web-address-www-google-com-in-a-web-browser-what-happens-before-we-get-the-resp', '<p>When we type a web address (www.google.com) in a web browser, what happens before we get the response?</p>', 'ef1223c162d907da9e97b53360beb0f5073870ee5f1891994d7b082a17380824', 0, 0, NULL, NULL);
