INSERT INTO solutions (id, question_id, created_by, code, language, status, runtime, memory) VALUES (78, 153, NULL, '<div class="language-sql vp-adaptive-theme"><button class="copy" title="Copy Code"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> INDEX</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> user_email_index</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users (user_email);</span></span></code></pre></div>', 'C++', NULL, NULL, NULL);
INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (154, '<p>Explain tree, binary tree, binary search tree. In a binary search tree, if the tree is imbalanced', 'p-explain-tree-binary-tree-binary-search-tree-in-a-binary-search-tree-if-the-tree-is-imbalanced', '<p>Explain tree, binary tree, binary search tree. In a binary search tree, if the tree is imbalanced, then how can we make it balanced?</p>', '6e64d516dc1a0c5e9cc2bb08281d304e6231f81b4343a7d4b1c034a3ee182823', 0, 0, 1, 21);
INSERT INTO companyquestions (id, company_id, question_id) VALUES (154, 6, 154);
INSERT INTO questiontopics (id, question_id, topic_id) VALUES (45, 154, 3);
INSERT INTO solutions (id, question_id, created_by, code, language, status, runtime, memory) VALUES (79, 154, NULL, '<ul><li><strong>Binary Tree</strong>:A binary tree is a tree data structure in which each node has at most two children, which are referred to as the left child and the right child.</li><li><strong>Binary Search Tree</strong>: A binary search tree is a binary tree in which the value of the left child is less than the parent node and the value of the right child is greater than the parent node.</li></ul><p>If the binary search tree is imbalanced, then we can make it balanced by using AVL tree or Red-Black tree. These trees are self-balancing binary search trees.</p>', 'plaintext', NULL, NULL, NULL);
INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (155, '<p>Explain the map, unordered_map and their complexity. Why does the complexity of the unordered_map', 'p-explain-the-map-unordered-map-and-their-complexity-why-does-the-complexity-of-the-unordered-map', '<p>Explain the map, unordered_map and their complexity. Why does the complexity of the unordered_map go to O(n) in some cases?</p>', '70a02e6706be5c44a6cc0fa5819bf1b68e8b5c4941edec58147e56cc4e8482e2', 0, 0, NULL, NULL);
INSERT INTO companyquestions (id, company_id, question_id) VALUES (155, 6, 155);
INSERT INTO solutions (id, question_id, created_by, code, language, status, runtime, memory) VALUES (80, 155, NULL, '<ul><li><strong>Map</strong>: A map is a data structure that stores key-value pairs. It is typically implemented as a balanced binary search tree, which gives it a time complexity of O(logn) for insertion, deletion, and search.</li><li><strong>Unordered Map</strong>: An unordered map is a data structure that stores key-value pairs. It is typically implemented as a hash table, which gives it an average time complexity of O(1) for insertion, deletion, and search. However, in the worst case, the time complexity can go up to O(n) if there are many collisions.</li></ul><p>Read more from <a href="https://www.geeksforgeeks.org/map-vs-unordered_map-c/" rel="noreferrer" target="_blank">Map vs Unordered Map in C++ | GeeksforGeeks</a></p>', 'plaintext', NULL, NULL, NULL);
INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (156, '<p>Explain the four principles of OOP.</p>', 'p-explain-the-four-principles-of-oop-p', '<p>Explain the four principles of OOP.</p>', '87c5ce48702938361034cb78c75645f31f01f1fdc451ea6866e4e47f1c07363d', 0, 0, NULL, NULL);
INSERT INTO companyquestions (id, company_id, question_id) VALUES (156, 6, 156);
INSERT INTO solutions (id, question_id, created_by, code, language, status, runtime, memory) VALUES (81, 156, NULL, '<p>The four main principles of Object-Oriented Programming (OOP) are:</p><ul><li><strong>Encapsulation</strong> – Bundling data and methods within a class while restricting direct access to some details.</li><li><strong>Abstraction</strong> – Hiding implementation details and exposing only essential functionalities.</li><li><strong>Inheritance</strong> – Enabling a class to derive properties and behavior from another class.</li><li><strong>Polymorphism</strong> – Allowing a single interface to represent different data types or methods (e.g., method overloading and overriding).</li></ul>', 'C++', NULL, NULL, NULL);
INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (157, '<p>Do you know there is an OOP feature which is only in C/C++?</p>', 'p-do-you-know-there-is-an-oop-feature-which-is-only-in-c-c-p', '<p>Do you know there is an OOP feature which is only in C/C++?</p>', 'db9373f6b56e39b635a6ea6e2e7dc2f69f7ab2eca00f750689763d9aa872991f', 0, 0, NULL, NULL);
INSERT INTO companyquestions (id, company_id, question_id) VALUES (157, 6, 157);
INSERT INTO solutions (id, question_id, created_by, code, language, status, runtime, memory) VALUES (82, 157, NULL, '<p>Operator overloading is a feature in C++ that allows operators to be redefined so that they work with user-defined types. This feature is not available in all OOP languages like Java or Python.</p>', 'plaintext', NULL, NULL, NULL);
INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (158, '<p>Explain the difference between an array and a linked list. Tell me some use cases for each of the', 'p-explain-the-difference-between-an-array-and-a-linked-list-tell-me-some-use-cases-for-each-of-the', '<p>Explain the difference between an array and a linked list. Tell me some use cases for each of them. How can we access an element of an array with the index?</p>', '8cb4137b2e637ee3f0447d59b1af7ccd31b1e4496234be2d49bf262ae2586950', 0, 0, NULL, NULL);
