INSERT INTO solutions (id, question_id, created_by, code, language, status, runtime, memory) VALUES (88, 165, NULL, '<ul><li><strong>JOIN</strong>: JOIN is used to combine rows from two or more tables based on a related column between them. There are different types of JOINs in SQL, such as INNER JOIN, LEFT JOIN, RIGHT JOIN, and FULL JOIN.</li><li><strong>Composite Key</strong>: A composite key is a combination of two or more columns in a table that can be used to uniquely identify each row in the table. A composite key is also known as a compound key.</li></ul>', 'plaintext', NULL, NULL, NULL);
