INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (183, '<p>There is a robot in a 4*4 matrix. The robot is initilly in cell (a,b) and wants to go to another ', 'p-there-is-a-robot-in-a-4-4-matrix-the-robot-is-initilly-in-cell-a-b-and-wants-to-go-to-another', '<p>There is a robot in a 4*4 matrix. The robot is initilly in cell (a,b) and wants to go to another cell (c,d). However, the robot doesn''t know the exact route and will move to any of its adjacent cell at equal probability. What is the probability that the robot will go from initial cell (a,b) to final cell (c,d) in exactly 4 moves.</p>', '2ca3cc9e88ec47aac3029ded6b7347cca780a49b483283e2177d869c15731c22', 0, 0, NULL, NULL);
INSERT INTO companyquestions (id, company_id, question_id) VALUES (183, 8, 183);
INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (184, '<p>There is a robot in a undirected tree. The robot will move from a node to any of its adjacent nod', 'p-there-is-a-robot-in-a-undirected-tree-the-robot-will-move-from-a-node-to-any-of-its-adjacent-nod', '<p>There is a robot in a undirected tree. The robot will move from a node to any of its adjacent node with equal probability. What is the expected number of moves required for the robot to go from node a to node b.</p>', 'a9b07fc8dd8204ae573f281f3a63840c03a406358a0bb2070db80ee4484d3749', 0, 0, NULL, NULL);
