INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (185, '<p>You are given an array of integers. You want to make the array non increasing. To do that you can', 'p-you-are-given-an-array-of-integers-you-want-to-make-the-array-non-increasing-to-do-that-you-can', '<p>You are given an array of integers. You want to make the array non increasing. To do that you can cut out a subsegment of the array to discard and concat the remaining segment(s). What is the minimum length of the cut segment to make the remaining parts nondecreasing.</p><p>Example: [9,7,4,3,6,6,2] : we can remove the subsegment containing [4,3] to make the array [9,7,6,6,2] or remove the segment [6,6] to make the array [9,7,4,3,2]. Both of them are non increasing.</p>', '37d3f3228fd929e42061fe8982586214b7723515a2db4adbd708642a66f8d280', 0, 0, NULL, NULL);
INSERT INTO companyquestions (id, company_id, question_id) VALUES (185, 8, 185);
