INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (204, '<p>Given an array of positive integers. We need to make the given array a ‘Palindrome’. The only all', 'p-given-an-array-of-positive-integers-we-need-to-make-the-given-array-a-palindrome-the-only-all', '<p>Given an array of positive integers. We need to make the given array a ‘Palindrome’. The only allowed operation is”merging” (of two adjacent elements). Merging two adjacent elements means replacing them with their sum. The task is to find the array of maximum length with the minimum number of merge operations required to make the given array a ‘Palindrome’.</p>', '30943c32ebcb93f611541cd2de1ad7d3ff868c0b379bf286195fa7fe1228a0ce', 0, 0, 1, 18);
