INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (205, '<p>Given an array of positive integers and a integer p. Find the length of the minimum subarray upon', 'p-given-an-array-of-positive-integers-and-a-integer-p-find-the-length-of-the-minimum-subarray-upon', '<p>Given an array of positive integers and a integer p. Find the length of the minimum subarray upon deleting which the sum of remaining element will be divisible by p;</p><p>Follow up 1: find the number of subarray (need not be minimum) deleting which will result the sum to be divisible by p</p><p>Follow up 2: For each index find the number of times it is included in any subarray upon deleting which the remaining sum will be divisible by p</p>', '1ea4ad931f62878fbd16ecbdc0bc87e74b7c774d2bc61249cb9a79f00989c58b', 0, 0, NULL, NULL);
