INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (206, '<p>You are given an array people and an integer limit, where people[i] is the weight of the ith pers', 'p-you-are-given-an-array-people-and-an-integer-limit-where-people-i-is-the-weight-of-the-ith-pers', '<p>You are given an array people and an integer limit, where people[i] is the weight of the ith person, and an infinite number of boats where each boat can carry a maximum weight of limit. Each boat carries at most two people at the same time, provided the sum of the weight of those people is at most limit.</p><p>Return the minimum number of boats to carry every given person.</p>', 'e5e34e264bd33fdd6f66ebaa02ee2df13371babc7e19fe065725aa16fe393bd9', 0, 0, NULL, NULL);
