INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (212, '<p>A permutation <code>P</code> is good if <code>P[i] % i == 0</code> or <code>i % P[i] == 0</code> ', 'p-a-permutation-code-p-code-is-good-if-code-p-i-i-0-code-or-code-i-p-i-0-code', '<p>A permutation <code>P</code> is good if <code>P[i] % i == 0</code> or <code>i % P[i] == 0</code> for <code>1 ≤ i ≤ N</code>. Given <code>N ≤ 20</code>, count the number of good permutations.</p>', '76d52a7cc714f0726f89fa2afe9177301e222f4f30971dba2fa629d6a253c539', 0, 0, NULL, NULL);
