INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (217, '<p>You are given an integer array <code>nums</code> and two integers <code>indexDiff</code> and <cod', 'p-you-are-given-an-integer-array-code-nums-code-and-two-integers-code-indexdiff-code-and-cod', '<p>You are given an integer array <code>nums</code> and two integers <code>indexDiff</code> and <code>valueDiff</code>. Find a pair of indices <code>(i, j)</code> such that: <code>i != j</code>, <code>abs(i - j) &lt;= indexDiff</code> and <code>abs(nums[i] - nums[j]) &lt;= valueDiff</code>.2025</p><p><strong>💻 Submit Code</strong></p>', '2433b44322028b8b99043203540bccc6556362388a5a7d4af4c7804890b67c6d', 0, 0, NULL, NULL);
