INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (221, '<p>You have a 2D grid representing a field with crop fields and godowns. Harvesters start at godowns', 'p-you-have-a-2d-grid-representing-a-field-with-crop-fields-and-godowns-harvesters-start-at-godowns', '<p>You have a 2D grid representing a field with crop fields and godowns. Harvesters start at godowns and collect crops from fields, bringing them back to their godown. The first harvester must collect from a specific number of fields. You need to calculate the minimum total time for all harvesters to collect all crops. 2024</p><p><strong>💻 Submit Code</strong></p>', '7590b3a3aa4010854ece0fbac76d730f2c89bf100fadd39c5ab5d7852f5b3cfc', 0, 0, NULL, NULL);
INSERT INTO companyquestions (id, company_id, question_id) VALUES (221, 11, 221);
INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (222, '<p>You have a list of unique strings and an empty list. You''ll be given queries to add strings to t', 'p-you-have-a-list-of-unique-strings-and-an-empty-list-you-ll-be-given-queries-to-add-strings-to-t', '<p>You have a list of unique strings and an empty list. You''ll be given queries to add strings to the empty list, delete strings from it, and count the number of strings between two given strings in the list after sorting it. 2024</p><p><strong>💻 Submit Code</strong></p><p>You are given a list <i>L</i> of <i>N</i> unique strings and an initially empty list <i>P</i>. You need to process <i>Q</i> queries of the following types:</p><ul><li><strong>add i f:</strong> Add the string <i>L[i]</i> to the list <i>P</i> a total of <i>f</i> times.</li><li><strong>delete i f:</strong> Let <i>t</i> be the number of occurrences of string <i>L[i]</i> in list <i>P</i>. Delete min(<i>f</i>, <i>t</i>) occurrences of <i>L[i]</i> from list <i>P</i>.</li><li><strong>count i j:</strong> Sort the elements of list <i>P</i> in lexicographic order, then count the number of strings in <i>P</i> that are between <i>L[i]</i> and <i>L[j]</i> (inclusive).</li></ul><p><strong>Constraints:</strong></p><ul><li><strong>1 ≤ N ≤ 105</strong> - Number of strings in list <i>L</i>.</li><li>The total length of all strings in <i>L</i> is at most 2 × 106, and each string length is between 1 and 106 characters.</li><li><strong>1 ≤ Q ≤ 105</strong> - Number of queries.</li><li>For <strong>add i f</strong> and <strong>delete i f</strong> queries: <strong>1 ≤ i ≤ N</strong> and <strong>1 ≤ f ≤ 105</strong>.</li><li>For <strong>count i j</strong> queries: <strong>1 ≤ i ≤ N</strong> and <strong>1 ≤ j ≤ N</strong>.</li></ul>', '2deca9941212ce470095933339df050808cb6a6e12c617c2c241d892d8f8a0de', 0, 0, NULL, NULL);
