INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (225, '<p>Given an array <code>A</code> of size <code>N</code> and some queries. Each query will ask for <c', 'p-given-an-array-code-a-code-of-size-code-n-code-and-some-queries-each-query-will-ask-for-c', '<p>Given an array <code>A</code> of size <code>N</code> and some queries. Each query will ask for <code>f(l,r)</code> where the function computes the sum of the greatest common divisors over all prefixes of some range <code>[l,r]</code>. Jr SWE 2025</p><p><strong>💻 Submit Code</strong></p>', '37c688b5359dd62b9daedc88d9b6d3c2c8532aaa8b13b3cbc897db056b044abe', 0, 0, NULL, NULL);
