INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (226, '<p>Given a permutation of size <code>N</code>. You will change the permutation repeatedly. In each o', 'p-given-a-permutation-of-size-code-n-code-you-will-change-the-permutation-repeatedly-in-each-o', '<p>Given a permutation of size <code>N</code>. You will change the permutation repeatedly. In each operation, you will create a new permutation b such that <code>b[i] = a[a[i]]</code> for all <code>1 ≤ i ≤ n</code>. Then replace <code>a</code> with <code>b</code>. You need to find the number of operations required to make the permutation sorted or report that it is impossible. Jr SWE 2025</p><p><strong>💻 Submit Code</strong></p>', 'b9fdd767d58b41a4c5742aafded6f17f914e32a7eecefb24c96b2681ac036b04', 0, 0, NULL, NULL);
INSERT INTO companyquestions (id, company_id, question_id) VALUES (226, 11, 226);
INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (227, '<p>Given a tree with <code>N</code> nodes. You will need to chose an optimal start node <code>s</cod', 'p-given-a-tree-with-code-n-code-nodes-you-will-need-to-chose-an-optimal-start-node-code-s-cod', '<p>Given a tree with <code>N</code> nodes. You will need to chose an optimal start node <code>s</code> such that the round trip distance from <code>s</code> to some given target nodes is minimized. Jr SWE 2025</p><p><strong>💻 Submit Code</strong></p>', 'cd1258055ae38f9486957217a5b82bf3a5883f0088e021f54f221bccfa550c9f', 0, 0, NULL, NULL);
