INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (228, '<p>Given a grid of size <code>N</code> and <code>M</code> with digit <code>0</code> and <code>1</cod', 'p-given-a-grid-of-size-code-n-code-and-code-m-code-with-digit-code-0-code-and-code-1-cod', '<p>Given a grid of size <code>N</code> and <code>M</code> with digit <code>0</code> and <code>1</code>. The grid indicates some patterns which are not connected. The patterns can be rotated or stretched too. You will need to find the patterns present in the grid. Jr SWE 2025</p><p><strong>💻 Submit Code</strong></p>', 'b452966522e9fcc9aae4aab3468d5a1de8de00d8d854504f778a654d8017f082', 0, 0, NULL, NULL);
