INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (237, '<p>JavaScript &amp; HTML</p><p>Write JavaScript code to check if a button is clicked in an HTML elem', 'p-javascript-html-p-p-write-javascript-code-to-check-if-a-button-is-clicked-in-an-html-elem', '<p>JavaScript &amp; HTML</p><p>Write JavaScript code to check if a button is clicked in an HTML element using an EventListener. Upon clicking, the size of the HTML element should increase by 10%.</p>', 'b6080ebcd90ade2affcb26d06ea97d3711897a64b87e240dc3554aabc9816ff2', 0, 0, NULL, NULL);
