INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (245, '<p>Design a system that will be used to monitor the usage of electricity of meters across a area. Th', 'p-design-a-system-that-will-be-used-to-monitor-the-usage-of-electricity-of-meters-across-a-area-th', '<p>Design a system that will be used to monitor the usage of electricity of meters across a area. The system should be able to show the usage of electricity in real time and also be able to show the usage of electricity over a period of time.</p><p>Answer varies from person to person. The interviewers are looking for a high level design of the system and are interested in the reasoning behind the design.</p>', '5d530e2aaeea09cad45a21983421a7a595966a112cef8637944f26fbd6cc9c96', 0, 0, NULL, NULL);
