INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (247, '<p>Discuss what led to the need for process scheduling in modern operating systems.<br> Explain how ', 'p-discuss-what-led-to-the-need-for-process-scheduling-in-modern-operating-systems-br-explain-how', '<p>Discuss what led to the need for process scheduling in modern operating systems.<br> Explain how multitasking and limited CPU resources made it necessary to manage processes efficiently, and describe the objectives of a process scheduler (e.g., fairness, responsiveness, throughput, CPU utilization).</p>', '5fb8375eb724ca59acdb35a66cab80920446bf8516cbb223622d8a26f0e6045d', 0, 0, NULL, NULL);
