INSERT INTO solutions (id, question_id, created_by, code, language, status, runtime, memory) VALUES (116, 248, NULL, '<p><img alt="" src="https://d8it4huxumps7.cloudfront.net/uploads/images/655df16819a37_compilation_in_c_01.jpg?d=2000x2000"/></p><ul><li><strong>Preprocessing:</strong> Handles directives like <code>#include</code> and <code>#define</code>.</li><li><strong>Compilation:</strong> Converts source code into assembly code.</li><li><strong>Assembling:</strong> Translates assembly code into machine code (object file).</li><li><strong>Linking:</strong> Combines object files and libraries to produce the final executable.</li></ul>', 'C++', NULL, NULL, NULL);
INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (249, '<p>Define the following fundamental computer science terms: DMA, Byte Order, coroutine, RISC, PCB.</', 'p-define-the-following-fundamental-computer-science-terms-dma-byte-order-coroutine-risc-pcb', '<p>Define the following fundamental computer science terms: DMA, Byte Order, coroutine, RISC, PCB.</p>', 'f32705b56baf1ad23b4b464b372a850741879643048a8ac24ee614f84fbc8ff8', 0, 0, NULL, NULL);
INSERT INTO companyquestions (id, company_id, question_id) VALUES (249, 16, 249);
INSERT INTO solutions (id, question_id, created_by, code, language, status, runtime, memory) VALUES (117, 249, NULL, '<ul><li><strong>DMA (Direct Memory Access):</strong> A feature that allows hardware devices to access main memory without CPU intervention.</li><li><strong>Byte Order (Endianness):</strong> The order in which bytes are stored for multi-byte data types; primarily little-endian vs. big-endian.</li><li><strong>Coroutine:</strong> A generalization of subroutines allowing execution to be paused and resumed; useful for cooperative multitasking.</li><li><strong>RISC (Reduced Instruction Set Computer):</strong> A CPU design philosophy focusing on a small, highly optimized set of instructions.</li><li><strong>PCB (Process Control Block):</strong> A data structure used by the operating system to store all information about a process (e.g., PID, state, registers, memory info).</li></ul>', 'plaintext', NULL, NULL, NULL);
INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (250, '<p>List and briefly describe the major parts of a CPU (Central Processing Unit):</p>', 'p-list-and-briefly-describe-the-major-parts-of-a-cpu-central-processing-unit-p', '<p>List and briefly describe the major parts of a CPU (Central Processing Unit):</p>', 'c564968475d910fd7c63c227aaa3c18d5bab8234cd1b4dbccf270ba297787408', 0, 0, NULL, NULL);
INSERT INTO companyquestions (id, company_id, question_id) VALUES (250, 16, 250);
INSERT INTO solutions (id, question_id, created_by, code, language, status, runtime, memory) VALUES (118, 250, NULL, '<ul><li><strong>ALU (Arithmetic Logic Unit):</strong> Performs arithmetic and logical operations.</li><li><strong>CU (Control Unit):</strong> Directs the operation of the processor by interpreting instructions.</li><li><strong>Registers:</strong> Small, fast memory locations for temporary data storage during instruction execution.</li><li><strong>Cache:</strong> A small-sized, high-speed memory for frequently accessed data.</li><li><strong>Clock:</strong> Synchronizes all operations and controls the pace of instruction execution.</li></ul>', 'plaintext', NULL, NULL, NULL);
INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (251, '<p>What happens when you type google.com and press enter in your search bar</p>', 'p-what-happens-when-you-type-google-com-and-press-enter-in-your-search-bar-p', '<p>What happens when you type google.com and press enter in your search bar</p>', '698f78df54a2bb44b20b5363513d0d9e9825896b963062db8e6d74514420d60f', 0, 0, NULL, NULL);
