INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (256, '<p>There are <code>10</code> jars of pills. One jar contains pills that weigh <code>9</code> grams e', 'p-there-are-code-10-code-jars-of-pills-one-jar-contains-pills-that-weigh-code-9-code-grams-e', '<p>There are <code>10</code> jars of pills. One jar contains pills that weigh <code>9</code> grams each, while the others contain pills weighing <code>10</code> grams each. Using a weighing scale only once, how can you determine which jar contains the lighter pills?</p>', '3b65ce59b986378629136160efb88050ce2907503c4943be1c04da63df22cdc1', 0, 0, NULL, NULL);
