INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (270, '<p>You are given <code>n</code> balloons, indexed from <code>0</code> to <code>n - 1</code>. Each ba', 'p-you-are-given-code-n-code-balloons-indexed-from-code-0-code-to-code-n-1-code-each-ba', '<p>You are given <code>n</code> balloons, indexed from <code>0</code> to <code>n - 1</code>. Each balloon is painted with a number on it represented by an array <code>nums</code>. You are asked to burst all the balloons.</p><p>If you burst the <code>ith</code> balloon, you will get <code>nums[i - 1] * nums[i] * nums[i + 1]</code> coins. If <code>i - 1</code> or <code>i + 1</code> goes out of bounds of the array, then treat it as if there is a balloon with a <code>1</code> painted on it.</p><p>Return the maximum coins you can collect by bursting the balloons wisely.</p><p>Variants: coins achieved is nums[i-1]*nums[i+1]</p><p><strong>💻 Submit Code</strong></p>', '8e0653071c60f5f63c1bfb45fda882b5f23358295d363027a182233d1901a46c', 0, 0, NULL, NULL);
