INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (271, '<p>A linked list of length <code>n</code> is given such that each node contains an additional random', 'p-a-linked-list-of-length-code-n-code-is-given-such-that-each-node-contains-an-additional-random', '<p>A linked list of length <code>n</code> is given such that each node contains an additional random pointer, which could point to any node in the list, or null. Construct a deep copy of the list.</p><p>The deep copy should consist of exactly <code>n</code> brand new nodes, where each new node has its value set to the value of its corresponding original node. Both the next and random pointer of the new nodes should point to new nodes in the copied list such that the pointers in the original list and copied list represent the same list state. None of the pointers in the new list should point to nodes in the original list.</p>', '9c1c1768b4c5c9b3b426637664d76dcd4c60c2843f2e907a106e80ecbf1f7665', 0, 0, NULL, NULL);
