INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (294, '<p>Given an array of sides of triangles, return an array of strings. The strings would be either “ye', 'p-given-an-array-of-sides-of-triangles-return-an-array-of-strings-the-strings-would-be-either-ye', '<p>Given an array of sides of triangles, return an array of strings. The strings would be either “yes” or “no”, corresponding to whether the same indexed triangle is a right triangle or not.</p><p>Input: <code>[[3,4,5], [5,9,12], [6,8,10]]</code> Output: <code>["yes","no","yes"]</code></p>', 'a006c092a78baf6a2e3801ccf716a00f667d58043bf9b828e64dcf3ded732d2f', 0, 0, NULL, NULL);
