INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (295, '<p>A dictionary of sorted words was like this: [a, above, bad, broke, cat,..., yes, yolk, zoo]. Afte', 'p-a-dictionary-of-sorted-words-was-like-this-a-above-bad-broke-cat-yes-yolk-zoo-afte', '<p>A dictionary of sorted words was like this: [a, above, bad, broke, cat,..., yes, yolk, zoo]. After a malfunction it became this: [..., yes, yolk, zoo, a, above, bad, broke, cat,....]. Write a program so that given a word, one can find the word in the dictionary, with the same time complexity as when the dictionary was sorted.</p><p><strong>💻 Submit Code</strong></p>', '1872916a2800374d3f931286e787ce2cb913d9eba5a892b131913690fb751667', 0, 0, NULL, NULL);
