INSERT INTO questions (id, title, slug, description, content_fingerprint, upvotes, downvotes, track_id, subtopic_id) VALUES (338, '<p>What is the time complexity of the following code?</p> C<pre><code>int fun(int n) {     if(n &lt;', 'p-what-is-the-time-complexity-of-the-following-code-p-c-pre-code-int-fun-int-n-if-n', '<p>What is the time complexity of the following code?</p>
